#!/usr/bin/env bash
set -euo pipefail
command -v node >/dev/null 2>&1 || { echo 'Node.js is required.' >&2; exit 1; }
node <<'AF_MINITAB_CONTROLS_NODE'
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/components/simulation/minitab-classroom.css": "/* These rules apply only to expanded Minitab activities. */\n.af-minitab-stage[data-expanded=\"true\"] {\n --af-minitab-plot-height: max(40px, calc(var(--af-stage-canvas-height, 70dvh) - 32px));\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-stage-main { overflow:hidden; }\n.af-minitab-stage[data-expanded=\"true\"] [data-stage-role=\"canvas\"] {\n display:flex; align-items:center; justify-content:center;\n width:100%; height:100%; min-height:0; overflow:hidden; padding:.5rem;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-canvas-frame {\n display:flex; align-items:center; justify-content:center;\n width:100%; height:100%; min-width:0; min-height:0; padding:.5rem;\n}\n.af-minitab-stage[data-expanded=\"true\"] canvas {\n width:100% !important; height:100% !important;\n max-width:100%; max-height:100%; object-fit:contain; object-position:center;\n margin:0;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-plot { width:100%; min-width:0; min-height:0; }\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-plot .recharts-cartesian-axis-tick-value,\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-plot .recharts-label { font-size:12px; }\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-transform-plots {\n display:grid; grid-template-columns:minmax(0,1fr); grid-template-rows:repeat(2,minmax(0,1fr));\n width:100%; height:100%; min-height:0; gap:.75rem;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-transform-plots > div {\n display:flex; flex-direction:column; min-height:0; margin:0;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-transform-plots .af-minitab-plot {\n flex:1 1 0; height:100% !important;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-transform-plots p { flex:0 0 auto; font-size:12px; }\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-scene {\n display:grid; grid-template-columns:minmax(0,1fr); grid-template-rows:minmax(0,1fr) minmax(0,1fr) auto; gap:.5rem;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-scene > div { height:100%; min-height:0; margin:0; }\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-scene > .af-minitab-canvas-frame { grid-column:1; grid-row:1; }\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-scene > .af-minitab-damped-graph { grid-column:1; grid-row:2; }\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-scene > [data-stage-role=\"playback\"] { grid-column:1 / -1; grid-row:3; height:auto; }\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-graph {\n display:flex; flex-direction:column; padding:.5rem;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-graph .af-minitab-plot { flex:1 1 0; height:100% !important; }\n@media(min-width:900px), (orientation:landscape) {\n .af-minitab-stage[data-expanded=\"true\"] .af-minitab-transform-plots {\n  grid-template-columns:repeat(2,minmax(0,1fr)); grid-template-rows:minmax(0,1fr);\n }\n .af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-scene {\n  grid-template-columns:minmax(0,1fr) minmax(0,1.2fr); grid-template-rows:minmax(0,1fr) auto;\n }\n .af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-scene > .af-minitab-damped-graph { grid-column:2; grid-row:1; }\n .af-minitab-stage[data-expanded=\"true\"] .af-minitab-damped-scene > [data-stage-role=\"playback\"] { grid-row:2; }\n}\n\n/* Keep the interactive controls proportional to the classroom viewport. */\n.af-minitab-stage[data-expanded=\"true\"] { --af-minitab-slider-width:clamp(220px,28vw,520px); }\n.af-minitab-stage[data-expanded=\"true\"] .af-stage-parameters [data-stage-role=\"parameters\"] { align-items:center; }\n.af-minitab-stage[data-expanded=\"true\"] .af-stage-parameters div:has(> input[type=\"range\"]) {\n flex:0 0 auto; width:max-content; min-width:var(--af-minitab-slider-width); max-width:none;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-stage-parameters input[type=\"range\"] {\n flex:1 1 auto !important; width:var(--af-minitab-slider-width) !important;\n min-width:200px; min-height:44px; margin-inline:.5rem; cursor:pointer;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-stage-parameters :is(label,span) { font-size:13px; }\n.af-minitab-stage[data-expanded=\"true\"] .af-stage-parameters .af-minitab-live-readout {\n display:grid; grid-template-columns:repeat(6,minmax(120px,1fr)); gap:.5rem;\n width:max-content; min-width:min(900px,80vw); padding:.5rem;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-live-readout > p { grid-column:1 / -1; margin:0; }\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-live-readout .af-minitab-stat {\n display:flex; flex-direction:column; align-items:flex-start; gap:.3rem; margin:0;\n}\n.af-minitab-stage[data-expanded=\"true\"] .af-minitab-live-readout .af-minitab-stat span:last-child { font-size:15px; white-space:nowrap; }\n", "src/app/minitab/div-stokes/page.tsx": "'use client';\nimport { MinitabStage as SimulationStage } from '@/components/simulation/MinitabStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { DivStokesCanvas } from '@/components/simulation/DivStokesCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { FIELDS, boundaryIntegrals, areaIntegrals } from '@/lib/physics/divStokes';\n\nconst TEACHER_NOTES = [\n  \"Chapter 3's divergence theorem and Chapter 4's Stokes'/Green's theorem both say the same kind of thing: a boundary measurement equals an interior sum.\",\n  'Flux (F·n̂ around the edge) always equals ∬(∇·F)dA (divergence summed over the disk) — move or resize the disk and both numbers stay locked together.',\n  'Circulation (F·dl around the edge) always equals ∬(∇×F)_z dA (curl summed over the disk) — same guarantee, independently verified here by direct numerical integration.',\n  'Try the \"Rotation\" field: circulation is large and flux is exactly zero — a pure rotation has no divergence anywhere.',\n  'Try the \"Source\" field: flux is large and circulation is exactly zero — pure radial outflow has no curl anywhere.',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'For F=(x,y), find ∇·F.', a: '∇·F=∂x/∂x+∂y/∂y=1+1=2 (constant everywhere — matches the \"Source\" field always showing the same flux-per-area).' },\n  { q: 'For F=(−y,x), find ∇×F (the z-component).', a: '(∇×F)_z=∂x/∂x−∂(−y)/∂y=1−(−1)=2 (constant — matches \"Rotation\" always showing the same circulation-per-area).' },\n  { q: \"Explain why the disk's flux and ∬∇·F dA must always agree, using the 'tiling with tiny boxes' argument.\", a: 'Tiling the disk with a fine grid, each tiny box contributes flux (∇·F)×(its area); at every shared internal edge, outflow from one box exactly equals inflow to its neighbour, so those contributions cancel. Only the outer boundary survives — which is exactly the flux integral.' },\n  { q: 'For the \"Mixed\" field F=(x−y,x+y), find both ∇·F and (∇×F)_z.', a: '∇·F=1+1=2. (∇×F)_z=1−(−1)=2. Both are nonzero and equal here, matching what the live readout shows for this preset.' },\n  { q: 'Why does moving the disk to a different location not change the flux or circulation for the fields shown here?', a: 'All five preset fields have divergence and curl that are either constant or depend simply on position in a way that, combined with symmetric disk placement, gives the same total when integrated over any disk of the same radius — try it and check against the readout.' },\n];\n\nexport default function DivStokesPage() {\n  const [fieldIndex, setFieldIndex] = useState(0);\n  const [disk, setDisk] = useState({ cx: 0.5, cy: 0.3, r: 1.1 });\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 480, 480, 520);\n\n  const field = FIELDS[fieldIndex];\n  const { circulation, flux } = boundaryIntegrals(field, disk.cx, disk.cy, disk.r);\n  const { divIntegral, curlIntegral } = areaIntegrals(field, disk.cx, disk.cy, disk.r);\n\n  useTopicPreset(\"minitab-div-stokes\", { \"disk.r\": (value: number) => setDisk(current => ({ ...current, r: value })) }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapters 3–4</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Divergence &amp; Stokes&apos; Theorem Visualizer</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap gap-1.5\">\n            {FIELDS.map((f, i) => (\n              <button key={f.name} onClick={() => setFieldIndex(i)}\n                className={`text-xs px-3 py-2 rounded-lg border font-medium transition ${\n                  fieldIndex === i ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'\n                }`}>{f.name}</button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm flex justify-center\">\n                <DivStokesCanvas fieldIndex={fieldIndex} disk={disk} onDiskChange={setDisk} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <span className=\"text-xs text-gray-500 shrink-0\">Disk radius r</span>\n                <input aria-label=\"Disk radius\" type=\"range\" min={0.4} max={2.2} step={0.05} value={disk.r}\n                  onChange={e => setDisk(d => ({ ...d, r: Number(e.target.value) }))}\n                  className=\"flex-1\" style={{ accentColor: '#2563eb' }} />\n                <span className=\"text-xs font-mono text-gray-500 w-14 text-right\">{disk.r.toFixed(2)}</span>\n              </div>\n              <div data-stage-role=\"extra\"><p className=\"text-[11px] text-gray-400 px-1\">Drag the disk directly on the canvas to move it.</p></div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                {[\n                  { l: 'Flux ∮F·n̂dl', v: flux.toFixed(3), c: 'text-blue-600' },\n                  { l: '∬(∇·F)dA', v: divIntegral.toFixed(3), c: 'text-blue-600' },\n                  { l: 'Circulation ∮F·dl', v: circulation.toFixed(3), c: 'text-emerald-600' },\n                  { l: '∬(∇×F)_z dA', v: curlIntegral.toFixed(3), c: 'text-emerald-600' },\n                ].map(r => (\n                  <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">{r.l}</span>\n                    <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/gradient-explorer/page.tsx": "'use client';\nimport { MinitabStage as SimulationStage } from '@/components/simulation/MinitabStage';\nimport { useState, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { GradientExplorerCanvas } from '@/components/simulation/GradientExplorerCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { FIELDS } from '@/lib/physics/gradientField';\n\nconst TEACHER_NOTES = [\n  \"D_â φ = ∇φ · â replaces Chapter 1's slow limit-definition calculation with a single dot product — find ∇φ once at a point, then any directional derivative there is just a dot product away.\",\n  \"∇φ always points in the direction of steepest increase of φ, and its magnitude |∇φ| IS the steepest rate of increase.\",\n  \"Drag the gold handle until it's perpendicular to the green gradient arrow — the readout drops to ≈0. That's exactly why level curves and ∇φ are always perpendicular: moving along a level curve means φ doesn't change at all.\",\n  \"Drag the gold handle to point the opposite way from ∇φ and watch D_âφ hit its most negative value −|∇φ| — steepest decrease.\",\n  \"Try the saddle field x²−y² at the origin: ∇φ=0 there (a stationary point), and every direction gives D_âφ=0 — the classic saddle-point signature.\",\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'For φ=x²+y², find ∇φ at (1,1) and its magnitude.', a: '∇φ=(2x,2y)=(2,2) at (1,1). |∇φ|=√(4+4)=√8≈2.83.' },\n  { q: 'Using the gradient from above, find D_âφ in direction â=(1/√2,1/√2).', a: 'D_âφ=∇φ·â=2(1/√2)+2(1/√2)=4/√2=2√2≈2.83 — matches |∇φ| exactly, since â is aligned with ∇φ here.' },\n  { q: 'For φ=xy, find ∇φ at (2,3) and the direction of steepest ascent.', a: '∇φ=(y,x)=(3,2) at (2,3). Direction: (3,2)/|(3,2)|=(3,2)/√13≈(0.83,0.55).' },\n  { q: 'At what points does ∇φ=0 for φ=x²−y²?', a: 'Only at the origin (0,0), where both 2x=0 and −2y=0 — the saddle point.' },\n  { q: 'Explain why moving along a level curve always gives D_âφ=0.', a: 'A level curve is defined by φ=constant, so by definition φ does not change as you move along it — and D_âφ measures exactly that rate of change, so it must be zero in that direction.' },\n];\n\nexport default function GradientExplorerPage() {\n  const [fieldIndex, setFieldIndex] = useState(0);\n  const [point, setPoint] = useState({ x: 1.3, y: 0.9 });\n  const [angleDeg, setAngleDeg] = useState(45);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 480, 480, 520);\n\n  const field = FIELDS[fieldIndex];\n  const gx = field.gx(point.x, point.y), gy = field.gy(point.x, point.y);\n  const gmag = Math.hypot(gx, gy);\n  const rad = (angleDeg * Math.PI) / 180;\n  const dirDeriv = gx * Math.cos(rad) + gy * Math.sin(rad);\n  const phi = field.f(point.x, point.y);\n\n  let interpretation = 'D_âφ = ∇φ·â = |∇φ|cosθ — rotate the handle and watch this hold exactly.';\n  const cosAngle = gmag > 1e-6 ? dirDeriv / gmag : 0;\n  if (gmag < 0.05) {\n    interpretation = '∇φ ≈ 0 here — a stationary point. Every direction gives D_âφ ≈ 0.';\n  } else if (Math.abs(cosAngle) > 0.97) {\n    interpretation = cosAngle > 0\n      ? 'â is aligned with ∇φ — steepest increase, D_âφ at its maximum |∇φ|.'\n      : 'â points opposite to ∇φ — steepest decrease, D_âφ at its minimum −|∇φ|.';\n  } else if (Math.abs(dirDeriv) < 0.05 * gmag) {\n    interpretation = \"â is perpendicular to ∇φ — you're moving along the level curve; φ barely changes.\";\n  }\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapters 1–2</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Gradient &amp; Directional Derivative Explorer</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div data-stage-role=\"parameters\" className=\"flex flex-wrap gap-1.5\">\n            {FIELDS.map((f, i) => (\n              <button key={f.name} onClick={() => setFieldIndex(i)}\n                className={`text-xs px-3 py-2 rounded-lg border font-medium transition ${\n                  fieldIndex === i ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'\n                }`}>{f.name}</button>\n            ))}\n          </div>\n\n          <SimulationStage className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <div data-stage-role=\"canvas\" className=\"space-y-3 min-w-0\">\n              <div ref={canvasBoxRef} className=\"af-minitab-canvas-frame rounded-2xl border border-gray-200 bg-white p-3 shadow-sm flex justify-center\">\n                <GradientExplorerCanvas\n                  fieldIndex={fieldIndex} point={point} angleDeg={angleDeg}\n                  onPointChange={setPoint} onAngleChange={setAngleDeg}\n                  width={canvasSize.width} height={canvasSize.height}\n                />\n              </div>\n              <div data-stage-role=\"extra\" className=\"rounded-2xl border border-emerald-100 bg-emerald-50 p-4\">\n                <p className=\"text-xs text-emerald-900 leading-relaxed\">{interpretation}</p>\n              </div>\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-3\">\n              <label className=\"block text-sm text-gray-700\">Scalar field<select aria-label=\"Scalar field\" value={fieldIndex} onChange={e=>setFieldIndex(Number(e.target.value))} className=\"mt-1 w-full rounded-lg border border-gray-300 bg-white p-2\">{FIELDS.map((f,i)=><option key={f.name} value={i}>{f.name}</option>)}</select></label>\n              <div className=\"af-minitab-live-readout rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                {[\n                  { l: 'Point (x,y)', v: `(${point.x.toFixed(2)}, ${point.y.toFixed(2)})`, c: 'text-gray-700' },\n                  { l: 'φ(x,y)', v: phi.toFixed(3), c: 'text-gray-700' },\n                  { l: '∇φ', v: `(${gx.toFixed(2)}, ${gy.toFixed(2)})`, c: 'text-emerald-600' },\n                  { l: '|∇φ|', v: gmag.toFixed(3), c: 'text-emerald-600' },\n                  { l: 'â direction', v: `${angleDeg.toFixed(0)}°`, c: 'text-amber-600' },\n                  { l: 'D_âφ = ∇φ·â', v: dirDeriv.toFixed(3), c: 'text-indigo-600' },\n                ].map(r => (\n                  <div key={r.l} className=\"af-minitab-stat flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">{r.l}</span>\n                    <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                  </div>\n                ))}\n              </div>\n              <p className=\"text-[11px] text-gray-400 px-1\">Drag the blue point to move; drag the gold arrowhead to change direction â.</p>\n            </div>\n\n            <div data-stage-role=\"extra\" className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/hermite-laguerre-delta/page.tsx": "'use client';\nimport { MinitabStage as SimulationStage } from '@/components/simulation/MinitabStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { HermiteLaguerreGraph, DiracDeltaGraph } from '@/components/simulation/HermiteLaguerreDeltaGraph';\nimport { deltaIntegrals, testFn } from '@/lib/physics/hermiteLaguerreDelta';\n\nconst TEACHER_NOTES = [\n  'Hermite polynomials, weighted by e⁻ˣ², are exactly the spatial part of the quantum harmonic oscillator\\u2019s energy eigenstates — Hₙ(x)e⁻ˣ²/² is (up to normalisation) the n-th excited-state wavefunction.',\n  'Laguerre polynomials, weighted by e⁻ˣ, are exactly the radial part of the hydrogen atom\\u2019s wavefunctions — different n give different electron shells.',\n  'Chapter 11 defines δ(x) by two properties — zero everywhere except x=0, total area 1 — rather than by a formula, because no ordinary function has both at once.',\n  'Drag ε down toward zero on the delta tab: the pulse gets taller and narrower, the area stays exactly 1 the whole time, and ∫f(x)δ_ε(x)dx converges to f(0) — the sifting property, made concrete.',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'Using H₀=1, H₁=2x and the recurrence Hₙ₊₁=2xHₙ−2nHₙ₋₁, find H₂(x).', a: 'H₂=2xH₁−2(1)H₀=2x(2x)−2=4x²−2.' },\n  { q: 'Using L₀=1, L₁=1−x and the recurrence, find L₂(1).', a: '(n+1)Lₙ₊₁=(2n+1−x)Lₙ−nLₙ₋₁ with n=1,x=1: 2L₂=(3−1)(0)−1(1)=−1 → L₂(1)=−0.5.' },\n  { q: 'State the two defining properties of the Dirac delta function δ(x).', a: 'δ(x)=0 for all x≠0, and ∫₋∞^∞δ(x)dx=1 (all the \"mass\" concentrated at a single point).' },\n  { q: 'State the sifting property of δ(x).', a: '∫f(x)δ(x−a)dx=f(a) for any well-behaved f — the delta function \"picks out\" the value of f at the point where the delta spike sits.' },\n  { q: 'Why can no ordinary function satisfy both defining properties of δ(x) exactly?', a: 'A function that is zero everywhere except a single point has zero area under any reasonable (Riemann) integral, no matter how \"tall\" it is at that one point — so no ordinary function can have zero width AND nonzero total area. δ(x) is instead defined as the limit of a family of functions (like the narrowing Gaussian shown here), not as a function itself.' },\n];\n\nconst FN_OPTIONS = [\n  { value: 'quad', label: 'f(x) = x² · 0.15 + 1' },\n  { value: 'sin', label: 'f(x) = sin(x) · 0.8 + 2' },\n  { value: 'cube', label: 'f(x) = cubic' },\n];\n\nexport default function HermiteLaguerreDeltaPage() {\n  const [mode, setMode] = useState<'hermite' | 'laguerre' | 'delta'>('hermite');\n  const [shownH, setShownH] = useState([0, 1, 2, 3]);\n  const [shownL, setShownL] = useState([0, 1, 2, 3]);\n  const [epsExp, setEpsExp] = useState(0);\n  const [fname, setFname] = useState('quad');\n\n  const toggle = (arr: number[], set: (v: number[]) => void) => (i: number) =>\n    set(arr.includes(i) ? arr.filter(v => v !== i) : [...arr, i]);\n\n  const eps = Math.pow(10, epsExp);\n  const { area, sift } = mode === 'delta' ? deltaIntegrals(eps, fname) : { area: 0, sift: 0 };\n\n  useTopicPreset(\"minitab-hermite-laguerre-delta\", { \"epsExp\": setEpsExp }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapter 11</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Hermite, Laguerre &amp; the Dirac Delta</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1.5 flex-wrap\">\n            {(['hermite', 'laguerre', 'delta'] as const).map(m => (\n              <button key={m} onClick={() => setMode(m)}\n                className={`text-xs px-4 py-2 rounded-lg border font-medium capitalize transition ${mode === m ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200'}`}>\n                {m === 'delta' ? 'Dirac delta' : m}\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                {mode === 'hermite' && <HermiteLaguerreGraph mode=\"hermite\" shown={shownH} />}\n                {mode === 'laguerre' && <HermiteLaguerreGraph mode=\"laguerre\" shown={shownL} />}\n                {mode === 'delta' && <DiracDeltaGraph eps={eps} fname={fname} />}\n              </div>\n\n              <div data-stage-role=\"parameters\">{mode === 'hermite' && (\n                <div className=\"flex flex-wrap gap-1.5 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                  {Array.from({ length: 7 }, (_, i) => i).map(i => (\n                    <label key={i} className=\"flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded-lg border border-gray-100 cursor-pointer\">\n                      <input type=\"checkbox\" checked={shownH.includes(i)} onChange={() => toggle(shownH, setShownH)(i)} className=\"accent-indigo-600\" />H{i}\n                    </label>\n                  ))}\n                </div>\n              )}</div>\n              <div data-stage-role=\"parameters\">{mode === 'laguerre' && (\n                <div className=\"flex flex-wrap gap-1.5 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                  {Array.from({ length: 6 }, (_, i) => i).map(i => (\n                    <label key={i} className=\"flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded-lg border border-gray-100 cursor-pointer\">\n                      <input type=\"checkbox\" checked={shownL.includes(i)} onChange={() => toggle(shownL, setShownL)(i)} className=\"accent-indigo-600\" />L{i}\n                    </label>\n                  ))}\n                </div>\n              )}</div>\n              <div data-stage-role=\"parameters\">{mode === 'delta' && (\n                <div className=\"space-y-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                  <div className=\"flex items-center gap-3\">\n                    <span className=\"text-xs text-gray-500 shrink-0\">Narrow the pulse (ε)</span>\n                    <input aria-label=\"Pulse width epsilon\" type=\"range\" min={-2} max={0.3} step={0.02} value={epsExp} onChange={e => setEpsExp(Number(e.target.value))} className=\"flex-1\" style={{ accentColor: '#2563eb' }} />\n                    <span className=\"text-xs font-mono text-gray-500 w-16 text-right\">{eps.toFixed(3)}</span>\n                  </div>\n                  <select value={fname} onChange={e => setFname(e.target.value)} className=\"w-full rounded-lg border border-gray-300 bg-white px-2 py-1.5 text-xs text-gray-900\">\n                    {FN_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}\n                  </select>\n                </div>\n              )}</div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              {mode === 'delta' && (\n                <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                  <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                  {[\n                    { l: 'Total area ∫δ_ε dx', v: area.toFixed(4), c: 'text-indigo-600' },\n                    { l: '∫f(x)δ_ε(x)dx', v: sift.toFixed(4), c: 'text-emerald-600' },\n                    { l: 'f(0) (target)', v: testFn(fname, 0).toFixed(4), c: 'text-gray-700' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n                </div>\n              )}\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((note, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{note}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/embed/damped-oscillator/page.tsx": "'use client';\nimport { useCallback,useEffect,useRef,useState } from 'react';\nimport { MinitabStage } from '@/components/simulation/MinitabStage';\nimport { DampedOscillatorCanvas } from '@/components/simulation/DampedOscillatorCanvas';\nimport { DampedOscillatorGraph } from '@/components/simulation/DampedOscillatorGraph';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { dampedEmbedDefaults,dampedEmbedSettings } from '@/lib/physics/dampedEmbed';\n\nexport default function DampedOscillatorEmbed(){\n const [params,setParams]=useState(dampedEmbedDefaults),[controls,setControls]=useState(true);\n const [running,setRunning]=useState(false),[paused,setPaused]=useState(false),[time,setTime]=useState(0),[resetKey,setResetKey]=useState(0);\n const box=useRef<HTMLDivElement>(null),lastTick=useRef(0);\n const size=useResponsiveCanvasSize(box,380,300,1000);\n useEffect(()=>{setParams(dampedEmbedSettings(window.location.search));setControls(new URLSearchParams(window.location.search).get('controls')!=='0');},[]);\n useEffect(()=>{setRunning(false);setPaused(false);setTime(0);},[params]);\n const tick=useCallback((t:number)=>{const now=performance.now();if(now-lastTick.current>40||t===0){lastTick.current=now;setTime(t);}},[]);\n function reset(){setRunning(false);setPaused(false);setTime(0);setResetKey(k=>k+1);}\n return <main className=\"mx-auto max-w-6xl space-y-3 bg-gray-50 p-3 text-gray-900 sm:p-4\">\n <h1 className=\"text-sm font-semibold\">Damped oscillator</h1>\n <MinitabStage className=\"af-embed-stage space-y-3\">\n  <div data-stage-role=\"canvas\" className=\"af-minitab-damped-scene space-y-3\">\n   <div ref={box} className=\"af-minitab-canvas-frame flex justify-center rounded-2xl border border-gray-200 bg-white p-3\">\n    <DampedOscillatorCanvas key={resetKey} {...params} isRunning={running} isPaused={paused} onTick={tick} width={size.width} height={size.height}/>\n   </div>\n   <div className=\"af-minitab-damped-graph rounded-2xl border border-gray-200 bg-white p-3\">\n    <p className=\"mb-2 text-xs text-gray-600\">Displacement y(t) · time {time.toFixed(2)} s</p>\n    <DampedOscillatorGraph {...params} currentT={time}/>\n   </div>\n  </div>\n  {controls&&<div data-stage-role=\"parameters\" className=\"flex flex-wrap gap-4 rounded-xl border border-gray-200 bg-white p-3\">\n   {([\n    ['gamma','Damping γ',0,6,0.05,'1/s'],\n    ['omega0','Natural frequency ω₀',0.5,6,0.05,'rad/s'],\n    ['y0','Initial displacement',-2,2,0.1,''],\n    ['yp0','Initial velocity',-4,4,0.1,'/s'],\n   ] as const).map(([key,label,min,max,step,unit])=><label key={key} className=\"block text-xs text-gray-700\">{label}: {params[key]} {unit}<input aria-label={label} className=\"block w-56 accent-indigo-600\" type=\"range\" min={min} max={max} step={step} value={params[key]} onChange={e=>setParams(p=>({...p,[key]:Number(e.target.value)}))}/></label>)}\n  </div>}\n  {controls&&<div data-stage-role=\"playback\"><SimulationControls isRunning={running} isPaused={paused} onRun={()=>{setRunning(true);setPaused(false);}} onPause={()=>setPaused(p=>!p)} onReset={reset}/></div>}\n </MinitabStage>\n <a href=\"/minitab/damped-oscillator\" target=\"_blank\" rel=\"noreferrer\" className=\"text-xs text-indigo-700 underline\">Open full lesson</a>\n </main>;\n}\n", "src/lib/physics/dampedEmbed.ts": "export const dampedEmbedDefaults={gamma:0.8,omega0:2,y0:1,yp0:0};\nexport function dampedEmbedSettings(search:string){\n const q=new URLSearchParams(search);\n const n=(key:keyof typeof dampedEmbedDefaults,min:number,max:number)=>{\n  const text=q.get(key);const value=text?.trim()?Number(text):NaN;\n  return Number.isFinite(value)?Math.max(min,Math.min(max,value)):dampedEmbedDefaults[key];\n };\n return {gamma:n('gamma',0,6),omega0:n('omega0',0.5,6),y0:n('y0',-2,2),yp0:n('yp0',-4,4)};\n}\n", "checks/minitab-classroom.cjs": "const fs=require('fs'),path=require('path'),vm=require('vm'),ts=require('typescript'),assert=require('assert'),React=require('react');\nlet index=0,slots=[],pending=[],calls=[],ticks=[],rect={left:10,top:20,width:400,height:400};\nconst same=(a,b)=>a&&b&&a.length===b.length&&a.every((v,i)=>Object.is(v,b[i]));\nconst ctx=new Proxy({}, {get:(o,k)=>k in o?o[k]:(...a)=>calls.push([k,...a]),set:(o,k,v)=>(o[k]=v,true)});\nconst canvas={width:480,height:480,getContext:()=>ctx,getBoundingClientRect:()=>rect,setPointerCapture(){}};\nconst react={...React,useMemo:fn=>fn(),useRef(v){const i=index++;return slots[i]??(slots[i]={current:i===0?canvas:v});},useCallback(fn,deps){const i=index++;if(!same(slots[i]?.deps,deps))slots[i]={deps,fn};return slots[i].fn;},useEffect(fn,deps){const i=index++;if(!same(slots[i],deps)){slots[i]=deps;pending.push(fn);}}};\nfunction load(file){file=path.resolve(file);const module={exports:{}};const code=ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText;const req=id=>id==='react'?react:id==='react/jsx-runtime'?require(id):id==='recharts'?new Proxy({}, {get:(_,key)=>key}):id.startsWith('@/')?load('src/'+id.slice(2)+'.ts'):require(id);vm.runInNewContext(code,{module,exports:module.exports,require:req,Math,URLSearchParams,requestAnimationFrame:()=>1,cancelAnimationFrame:()=>{}});return module.exports;}\nconst {fitMinitabViewport:fit,minitabPointer:pointer}=load('src/lib/physics/minitabViewport.ts');\nfor(const [w,h]of [[320,480],[800,800],[1600,900],[2400,1200]]){const v=fit(w,h,480,480);assert(Math.abs(v.x+240*v.scale-w/2)<1e-8);assert(Math.abs(v.y+240*v.scale-h/2)<1e-8);assert(480*v.scale<=w+1e-8&&480*v.scale<=h+1e-8);}\nrect={left:10,top:20,width:1000,height:400};let p=pointer(canvas,510,220,480,480);assert.equal(p.x,240);assert.equal(p.y,240);\nfor(const name of ['EigenvectorCanvas','GradientExplorerCanvas','DivStokesCanvas','DampedOscillatorCanvas']){\n slots=[];index=0;let moved;\n const Component=load('src/components/simulation/'+name+'.tsx')[name];const base=name==='EigenvectorCanvas'?460:name==='DampedOscillatorCanvas'?380:480;const baseH=name==='DampedOscillatorCanvas'?300:base;\n const props={matrix:{a:1,b:0,c:0,d:1},t:0,fieldIndex:0,disk:{cx:0,cy:0,r:1},point:{x:0,y:0},angleDeg:45,onDiskChange:v=>moved=v,onPointChange:v=>moved=v,onAngleChange:()=>{},gamma: